#include <iostream>
#include <string>
#include <stdexcept>
using namespace std;

template <typename T>
class Queue {
private:
    struct Node {
        T item;
        Node* next;
        Node(T value, Node* link = nullptr) : item(value), next(link) {}
    };
    Node* head;
    Node* tail;
public:
    Queue() : head(nullptr), tail(nullptr) {}
    // This object owns its nodes. Disable shallow copying.
    Queue(const Queue&) = delete;
    Queue& operator=(const Queue&) = delete;
    ~Queue() {
        while (head != nullptr) {
            Node* old = head;
            head = head->next;
            delete old;
        }
    }
    bool isEmpty() const { return head == nullptr; }
    void enqueue(T item) {
        Node* node = new Node(item);
        if (isEmpty()) head = node;
        else tail->next = node;
        tail = node;
    }
    T front() const {
        if (isEmpty()) throw runtime_error("Empty queue");
        return head->item;
    }
    T dequeue() {
        if (isEmpty()) throw runtime_error("Empty queue");
        Node* old = head;
        T value = old->item;
        head = head->next;
        if (head == nullptr) tail = nullptr;
        delete old;
        return value;
    }
};

use:
Queue<int> numbers;
numbers.enqueue(10);
numbers.enqueue(20);
numbers.enqueue(30);
cout << numbers.dequeue() << '\n';
cout << numbers.dequeue() << '\n';
numbers.enqueue(40);
while (!numbers.isEmpty()) {
    cout << numbers.dequeue() << '\n';
}
try {
    numbers.dequeue();
} catch (const runtime_error& error) {
    cout << error.what() << '\n';
}

