#include <iostream>
#include <string>
using namespace std;

class Job {
protected:
    int id;
public:
    Job(int jobId) : id(jobId) {}
    virtual void execute() const = 0;
    virtual ~Job() = default;
};

class PrintJob : public Job {
private:
    string filename;
public:
    PrintJob(int jobId, string file)
        : Job(jobId), filename(file) {}

    void execute() const override {
        cout << "Print job " << id << ": " << filename << '\n';
    }
};

class BackupJob : public Job {
private:
    string folder;
public:
    BackupJob(int jobId, string folderName)
        : Job(jobId), folder(folderName) {}

    void execute() const override {
        cout << "Backup job " << id << ": " << folder << '\n';
    }
};

use:
PrintJob print(1, "notes.pdf");
BackupJob backup(2, "coursework");
Job* jobs[] = {&print, &backup};
for (Job* job : jobs) {
    job->execute();
}

